{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Abemaciclib has an absolute oral bioavailability of 45% in humans after a 200-mg oral dose, a direct human F measurement well above the 20% threshold; its assay-transfer score of 0.9913 strongly supports applicability to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Doxazosin has an absolute oral bioavailability of 60-70% in healthy subjects, direct human F evidence well above the threshold; assay-transfer score 0.9909 supports strong transfer to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Mizolastine has an absolute oral bioavailability of 70% for capsules in healthy young volunteers, direct human F evidence above the threshold; assay-transfer score 0.9904 supports strong transfer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Abecarnil has an absolute oral bioavailability of 39 ± 17% (range 23-70%) in healthy male volunteers, direct human F evidence above the threshold; assay-transfer score 0.9906 supports strong transfer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Gefitinib has an oral bioavailability of approximately 60% in humans, direct human F evidence above the threshold; assay-transfer score 0.9905 supports strong transfer.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "ONO-4641 has a predicted human bioavailability of 0.710, a human PK simulation result above the threshold; assay-transfer score 0.9915 supports strong transfer.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple high-transfer human absolute bioavailability measurements (abemaciclib 45%, doxazosin 60-70%, mizolastine ~65-70%, abecarnil 39%, gefitinib ~60%) consistently support F >= 20%. The physicochemical prior is uncertain and is overridden by direct experimental evidence from closely transferable analogues; predict high.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself.",
    "The query's zwitterionic and low-neutral-fraction physicochemical profile is not directly tested in the analogue evidence, leaving residual uncertainty about whether these liabilities would reduce F in this specific scaffold.",
    "Some supporting records are predicted or simulated rather than measured absolute F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

